const list = $('Database1').first().json.result?.assets ?? [];
const items = [], failed = [];
let error = null;
for (const a of list) {
  try {
    const tags = await makeKeywords(a);
    if (tags.length) items.push({ id: a.id, tags }); else failed.push(a.name);
  } catch (e) {
    error = String(e.message || e).slice(0, 200);
    failed.push(a.name);
    if (/not found|404|ECONNREFUSED|ENOTFOUND|EAI_AGAIN/i.test(error)) break;   // modello mancante o Ollama spento: inutile insistere
  }
}
const P = s => JSON.stringify(s).split('$xrq$').join('');
const sql = items.length ? "WITH p AS (SELECT $xrq${P}$xrq$::jsonb AS j),\nup AS (\n  UPDATE xr.assets a SET tags = ARRAY(SELECT jsonb_array_elements_text(x.tags)), updated_at = now()\n  FROM p, jsonb_to_recordset(COALESCE(p.j->'items','[]'::jsonb)) AS x(id uuid, tags jsonb)\n  WHERE a.id = x.id AND cardinality(a.tags) = 0 AND jsonb_array_length(x.tags) > 0\n  RETURNING a.id\n)\nSELECT json_build_object('ok', true, 'updated', (SELECT count(*) FROM up)) AS result;".split('{P}').join(P({ items })) : "SELECT json_build_object('ok', true, 'updated', 0) AS result;";
return [{ json: { sql, processed: items.length, failed, error } }];

// Esito di un blocco di arricchimento: quanti aggiornati, quanti ne mancano
const src = $('Parole chiave in blocco1').first().json;
const total = Number($('Database1').first().json.result?.remaining ?? 0);
const updated = Number($input.first().json.result?.updated ?? 0);
const remaining = Math.max(0, total - updated);
const hardError = updated === 0 && src.error;
return [{ json: { result: { ok: !hardError, processed: updated, failed: src.failed, remaining,
  error: hardError ? (src.error + ` — controlla che il modello "llama3.2" sia installato (docker compose exec ollama ollama pull llama3.2)`) : null } } }];
